def null_geometry(q):
 n=sagittal_null_vector(q,runner.base.HIGH_ROM_HUMAN);w=sagittal_wrench_to_world_matrix(q,runner.base.HIGH_ROM_HUMAN)@n;d=w[:3]/np.linalg.norm(w[:3]);B=sagittal_allocation_matrix(q,runner.base.HIGH_ROM_HUMAN)
 return n,w,d,float(np.linalg.cond(B))
def min_force(force,d):
 p=float(force@d);return float(np.linalg.norm(force-p*d)),-p

def rigid_mechanism(rigid):
 rid=rigid['run_id'];path=ROOT/rid;z=load(path/'trace.npz');md=load(path/'modes.npz');c=load(path/'commands.npz');res=rigid['raw_result']
 fi=np.flatnonzero(z['safety_filter_status'].astype(str)=='FILTER_INFEASIBLE');assert len(fi)==1
 ei=int(fi[0]);pi=ei-1;te=float(z['safety_filter_time_s'][ei]);tp=float(z['safety_filter_time_s'][pi])
 cie=nearest(z['control_time_s'],te);cip=nearest(z['control_time_s'],tp);qe=z['control_estimated_state'][cie,:2];qp=z['control_estimated_state'][cip,:2]
 npv,wp,dp,condp=null_geometry(qp);nev,we,de,conde=null_geometry(qe)
 kp=nearest(c['time_s'],tp);lam=float(z['safety_filter_lambda'][pi]);filtered_total=c['force'][kp];nominal_prev=filtered_total-lam*dp
 api=min(int(np.searchsorted(z['time_s'],tp+1e-8)),len(z['time_s'])-1);filtered_alloc=z['allocated_wrench_world'][api];nominal_alloc_prev=filtered_alloc-lam*wp
 last=res['brake']['last_safety_filter'];nominal_event=np.asarray(last['nominal_force_total_n']);nominal_alloc_event=np.asarray(last['nominal_wrench_world'])
 mp,bp=min_force(nominal_prev,dp);me,be=min_force(nominal_event,de)
 fbp=nominal_prev-nominal_alloc_prev[:3];fbe=nominal_event-nominal_alloc_event[:3]
 modei=nearest(md['time_s'],te);updates=np.flatnonzero((md['time_s']<=te)&(md['mpc_status'].astype(str)!='NO_NEW_MPC'));last_update=float(md['time_s'][updates[-1]]) if len(updates) else None
 total_change=nominal_event-nominal_prev;alloc_change=nominal_alloc_event[:3]-nominal_alloc_prev[:3];feedback_change=fbe-fbp
 same=bool(mp<=200+1e-6 and me>200 and np.linalg.norm(feedback_change)>np.linalg.norm(alloc_change))
 return clean(dict(event_time_s=te,previous_time_s=tp,reference_phase_s=float(np.interp(te,z['time_s'],z['reference_phase_time_s'])),outbound_reference_percent=rigid['outbound_reference_percent'],q_event_deg=np.degrees(qe),dq_event_deg_s=np.degrees(z['control_estimated_state'][cie,2:]),q_change_deg=np.degrees(qe-qp),dq_change_deg_s=np.degrees(z['control_estimated_state'][cie,2:]-z['control_estimated_state'][cip,2:]),human_B_condition_previous=condp,human_B_condition_event=conde,null_direction_change_deg=float(np.degrees(np.arccos(np.clip(dp@de,-1,1)))),nominal_force_previous_n=nominal_prev,nominal_force_event_n=nominal_event,nominal_force_change_n=total_change,nominal_force_norm_previous_n=float(np.linalg.norm(nominal_prev)),nominal_force_norm_event_n=float(np.linalg.norm(nominal_event)),minimum_achievable_force_previous_n=mp,minimum_achievable_force_event_n=me,best_lambda_previous=bp,best_lambda_event=be,applied_lambda_previous=lam,allocator_force_previous_n=nominal_alloc_prev[:3],allocator_force_event_n=nominal_alloc_event[:3],allocator_force_change_n=alloc_change,feedback_force_previous_n=fbp,feedback_force_event_n=fbe,feedback_force_change_n=feedback_change,feedback_change_norm_n=float(np.linalg.norm(feedback_change)),allocator_change_norm_n=float(np.linalg.norm(alloc_change)),event_decision_status=str(md['decision_status'][modei]),event_feasible_candidate_count=int(md['feasible_candidate_count'][modei]),last_cem_update_time_s=last_update,mpc_status_at_event=str(md['mpc_status'][modei]),same_mechanism_as_40_80=same,mechanism_statement='feedback-dominated nominal wrench change makes torque-preserving minimum achievable force exceed 200 N' if same else 'not established'))

