def main():
 s=read(SPEC);reg=read(ROOT/'registration.json');assert sha(SPEC)==sha(ROOT/SPEC.name)==reg['spec_sha'];assert sha(DOC)==sha(ROOT/DOC.name)==reg['md_sha'];assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip()==s['head'];assert not subprocess.check_output(['git','diff','--name-only','HEAD'],cwd=REPO,text=True).strip()
