 (ROOT/'REPORT.md').write_text('\n\n'.join(report)+'\n')
 validation=dict(spec_sha=reg['spec_sha'],md_sha=reg['md_sha'],head=s['head'],executed_runs=2,unique_process_ids=[x['pid'] for x in started],paired_initial_state_exact=True,paired_config_equal_except_interface=True,frozen_hashes_verified=len(s['frozen_hashes']),implementation_hashes_verified=len(reg['implementation_hashes']),postprocessor_sha=sha(Path(__file__)),no_simulation=True,no_additional_trajectory=True,strict_numerical_qualification='FAIL_PRESERVED')
 (ROOT/'postprocess_validation.json').write_text(json.dumps(validation,indent=2,sort_keys=True)+'\n')
