 print(json.dumps(clean(dict(validation=validation,rigid_mechanism=mechanism,summary={a:{k:save_metrics[a][k] for k in ['formal_classification','termination_reason','outbound_reference_percent','return_reference_percent','physical_outbound_sync_peak_percent','human_target_reached','human_return_reached','tracking_rmse_deg']} for a in ['rigid','P1']})),indent=2))
